package kr.gyeollon;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.Test;
import java.net.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class TeslaIntegrationTest {
 final ObjectMapper mapper=new ObjectMapper();
 static class MutableClock extends Clock {Instant now=Instant.parse("2026-01-01T00:00:00Z");public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now;}}
 class Fake implements TeslaIntegration.Gateway {int refresh=0;boolean denied=false; boolean empty=false;boolean noPermission=false;boolean badToken=false;boolean online=false;boolean location=false;String failPath=null;
  public JsonNode token(Map<String,String> f)throws TeslaIntegration.Failure{if(denied)throw new TeslaIntegration.Failure("REAUTH_REQUIRED");if(f.get("grant_type").equals("refresh_token"))refresh++;try{return mapper.readTree(badToken?"{}":"{\"access_token\":\"fake-access\",\"refresh_token\":\"fake-refresh\",\"expires_in\":60}");}catch(Exception e){throw new AssertionError();}}
  public JsonNode get(String p,String t)throws TeslaIntegration.Failure{if(noPermission)throw new TeslaIntegration.Failure("PERMISSION_DENIED");if(failPath!=null && p.endsWith(failPath))throw new TeslaIntegration.Failure("NO_DATA");try{return mapper.readTree(p.endsWith("/users/region")?"{\"response\":{\"fleet_api_base_url\":\"https://fleet-api.prd.na.vn.cloud.tesla.com\"}}":p.contains("?endpoints=location_data")?(location?"{\"response\":{\"drive_state\":{\"latitude\":37.5,\"longitude\":127.0,\"timestamp\":1767225600000}}}":"{\"response\":{}}"):p.endsWith("TEST_VIN")?(online?"{\"response\":{\"state\":\"online\"}}":"{\"response\":{\"state\":\"asleep\"}}"):p.endsWith("vehicles")?(empty?"{\"response\":[]}":"{\"response\":[{\"vin\":\"TEST_VIN\",\"display_name\":\"test\",\"state\":\"asleep\"}]}"):"{\"response\":{\"charge_state\":{\"battery_level\":70,\"est_battery_range\":100,\"timestamp\":1767225600000}}}");}catch(Exception e){throw new AssertionError();}}
 }
 String state(String url){return Arrays.stream(URI.create(url).getRawQuery().split("&")).filter(x->x.startsWith("state=")).findFirst().orElseThrow().substring(6);}
 @Test void oauthStateRefreshAndRevocation()throws Exception{var clock=new MutableClock();var fake=new Fake();var svc=new TeslaIntegration("id","secret","https://example.test/api/tesla/callback",fake,clock);var session=new TeslaIntegration.Session();String a=state(svc.begin(session,false));assertEquals("INVALID_STATE",assertThrows(TeslaIntegration.Failure.class,()->svc.callback(session,"wrong","code",null)).code);assertEquals("INVALID_STATE",assertThrows(TeslaIntegration.Failure.class,()->svc.callback(session,a,"code",null)).code);String next=state(svc.begin(session,false));svc.callback(session,next,"code",null);assertTrue(svc.connected(session));clock.now=clock.now.plusSeconds(40);svc.vehicles(session);assertEquals(1,fake.refresh);fake.denied=true;clock.now=clock.now.plusSeconds(40);assertEquals("REAUTH_REQUIRED",assertThrows(TeslaIntegration.Failure.class,()->svc.vehicles(session)).code);assertFalse(svc.connected(session));}
 @Test void denialExpiryAndDisconnect()throws Exception{var c=new MutableClock();var f=new Fake();var svc=new TeslaIntegration("id","secret","https://example.test/api/tesla/callback",f,c);var s=new TeslaIntegration.Session();String a=state(svc.begin(s,false));assertEquals("AUTHORIZATION_DENIED",assertThrows(TeslaIntegration.Failure.class,()->svc.callback(s,a,null,"denied")).code);String b=state(svc.begin(s,false));c.now=c.now.plusSeconds(301);assertEquals("INVALID_STATE",assertThrows(TeslaIntegration.Failure.class,()->svc.callback(s,b,"code",null)).code);String d=state(svc.begin(s,false));svc.callback(s,d,"code",null);svc.disconnect(s);assertFalse(svc.connected(s));}
 @Test void vehiclesCachedAndPermission()throws Exception{var c=new MutableClock();var f=new Fake();var svc=new TeslaIntegration("id","secret","https://example.test/api/tesla/callback",f,c);var s=new TeslaIntegration.Session();svc.callback(s,state(svc.begin(s,false)),"code",null);f.empty=true;assertTrue(svc.vehicles(s).isEmpty());f.empty=false;var car=svc.vehicles(s).get(0);assertEquals("asleep",car.state());assertNotEquals("TEST_VIN",car.id());svc.select(s,car.id());assertEquals("OFFLINE_OR_ASLEEP",assertThrows(TeslaIntegration.Failure.class,()->svc.location(s)).code);f.online=true;assertEquals("LOCATION_UNAVAILABLE",assertThrows(TeslaIntegration.Failure.class,()->svc.location(s)).code);f.location=true;assertEquals(37.5,svc.location(s).latitude());var data=svc.reading(s);assertEquals(70,data.batteryPercent());assertEquals(160.9,data.estimatedRangeKm());assertEquals("NOT_AVAILABLE_IN_CACHED_DATA",data.locationStatus());assertFalse(data.stale());c.now=c.now.plusSeconds(901);assertTrue(svc.reading(s).stale());f.noPermission=true;assertEquals("REGION_PERMISSION_DENIED",assertThrows(TeslaIntegration.Failure.class,()->svc.vehicles(s)).code);assertEquals("[redacted]",s.toString());}
 @Test void distinguishEmptyAndFailedStages()throws Exception{var c=new MutableClock();var f=new Fake();var svc=new TeslaIntegration("id","secret","https://example.test/callback",f,c);var s=new TeslaIntegration.Session();svc.callback(s,state(svc.begin(s,false)),"code",null);f.failPath="/users/region";assertEquals("REGION_ENDPOINT_UNAVAILABLE",assertThrows(TeslaIntegration.Failure.class,()->svc.vehicles(s)).code);f.failPath="/vehicles";assertEquals("VEHICLE_LIST_ENDPOINT_UNAVAILABLE",assertThrows(TeslaIntegration.Failure.class,()->svc.vehicles(s)).code);f.failPath=null;f.empty=true;assertTrue(svc.vehicles(s).isEmpty());} @Test void preconditionIsNotMissingData()throws Exception{
  assertEquals("PRECONDITION_FAILED",assertThrows(TeslaIntegration.Failure.class,()->TeslaIntegration.HttpGateway.checkStatus(412,"/api/1/users/region")).code);
  assertEquals("NO_DATA",assertThrows(TeslaIntegration.Failure.class,()->TeslaIntegration.HttpGateway.checkStatus(412,"/api/1/vehicles/test/vehicle_data_cached")).code);
  assertEquals("NO_DATA",assertThrows(TeslaIntegration.Failure.class,()->TeslaIntegration.HttpGateway.checkStatus(404,"/api/1/users/region")).code);
  assertEquals("PAYMENT_REQUIRED",assertThrows(TeslaIntegration.Failure.class,()->TeslaIntegration.HttpGateway.checkStatus(402,"/api/1/users/region")).code);
  assertEquals("INCORRECT_REGION",assertThrows(TeslaIntegration.Failure.class,()->TeslaIntegration.HttpGateway.checkStatus(421,"/api/1/users/region")).code);
  assertDoesNotThrow(()->TeslaIntegration.HttpGateway.checkStatus(200,"/api/1/users/region"));
 }
}
